installer-gui-script.script:
function scalaExtensionAbsent() {
    var scala = system.env.HOME + '/Library/Application Support/Zed/extensions/installed/scala';
    if (system.files.fileExistsAtPath(scala)) {
        my.result.title = "Zed's Scala extension is installed";
        my.result.message = "Uninstall it from Zed's extensions page first: Zed runs one Scala language at a time, and this extension brings its own. If auto_install_extensions in Zed's settings lists \"scala\", remove that too, or Zed installs it again. Then run this installer again.";
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
